-- Portable promotion-style migration linking the TR Undoing
-- Changes quiz questions to the topic's existing fixed quiz -- same pattern as
-- git-fundamentals/V467-V468 and working-with-commits/V469-V470 (see those
-- files for the full rationale).
--
-- Development Question IDs: 145, 146, 147, 148, 149, 150, 151, 152, 153, 154
-- Topic: undoing-changes (language: tr)
-- Turkish counterparts of the English questions in V471 -- same learning
-- objectives, not literal translations. Generated by Claude and
-- auto-published via the same AI-Judge auto-publish endpoint after the
-- same self-review -- see chat transcript.

-- Each question is RE-INSERTED here with its full content via
-- WITH ... RETURNING id (question-promotion/V431's mechanism) -- portable to
-- any environment, no hardcoded foreign ids. topic_id is resolved by
-- Topic.slug, and the quiz is resolved by (topic slug, language='tr', quiz
-- slug='default') -- the EXISTING fixed quiz for this topic, not a new one.
--
-- Content was captured AFTER these questions were auto-published (status=
-- PUBLISHED, reviewed_by='n8n-ai-judge', real reviewed_at) -- NOT before, per
-- the lesson learned while building git-fundamentals/V468 (bkz.
-- docs/known-constraints.md): a fallback branch generated from pre-publish
-- content would silently create PENDING_REVIEW rows on any fresh database.
--
-- Duplicate-safety: each block first checks whether an equivalent question
-- row (same topic_id + language='tr' + exact question text) already
-- exists, and only INSERTs when it doesn't -- portable to a fresh database,
-- and a safe no-op if re-run against this development database (where the
-- content already exists from live ingestion). The quiz_question_link insert
-- carries ON CONFLICT DO NOTHING as a second safety net (UNIQUE(quiz_id,
-- question_id), UNIQUE(quiz_id, position) from V290).


-- Question 1/10 (dev id 145, quiz position 1)
WITH existing_q1 AS (
    SELECT id FROM question
    WHERE topic_id = (SELECT id FROM topic WHERE slug = 'undoing-changes')
      AND language = 'tr'
      AND question = $$Bir dosyayı düzenledin ama henüz stage'lemediysen, `git restore <dosya>` çalıştırmak ne yapar?$$
),
inserted_q1 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'tr', 'SINGLE_CHOICE', 'BEGINNER', 'PUBLISHED', 'CLAUDE',
           $$Bir dosyayı düzenledin ama henüz stage'lemediysen, `git restore <dosya>` çalıştırmak ne yapar?$$, NULL, NULL,
           $$`git restore` yalnızca working tree'ye dokunur — commit edilmemiş düzenlemeyi atar ve dosyayı son commit edilmiş sürüme döndürür. Bir dosyayı asla unstage etmez (bunun için `--staged` gerekir) ve HEAD'e dokunmaz.$$, 'n8n-ai-judge', '2026-08-29 15:08:40.454197',
           now(), now()
    FROM topic
    WHERE slug = 'undoing-changes'
      AND NOT EXISTS (SELECT 1 FROM existing_q1)
    RETURNING id
),
target_q1 AS (
    SELECT id, TRUE AS newly_inserted FROM inserted_q1
    UNION ALL
    SELECT id, FALSE AS newly_inserted FROM existing_q1
),
option_ins_q1 AS (
    INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT target_q1.id, v.option_text, v.is_correct, v.sort_order
    FROM target_q1
             CROSS JOIN (VALUES
    ($$Working tree'deki commit edilmemiş düzenlemeyi atar, dosyayı son commit edilmiş sürüme döndürür.$$, TRUE, 0),
    ($$Dosyayı staging area'dan working tree'ye geri taşıyarak unstage eder.$$, FALSE, 1),
    ($$HEAD'i önceki commit'e taşıyarak son commit'i geri alır.$$, FALSE, 2),
    ($$Değişikliği tersine çeviren yeni bir commit oluşturur.$$, FALSE, 3)
        ) AS v(option_text, is_correct, sort_order)
    WHERE target_q1.newly_inserted
    RETURNING 1
)
INSERT INTO quiz_question_link (quiz_id, question_id, position)
SELECT quiz.id, target_q1.id, 1
FROM target_q1
         JOIN quiz ON TRUE
         JOIN topic t ON t.id = quiz.topic_id
WHERE t.slug = 'undoing-changes'
  AND quiz.language = 'tr'
  AND quiz.slug = 'default'
ON CONFLICT (quiz_id, question_id) DO NOTHING;


-- Question 2/10 (dev id 146, quiz position 2)
WITH existing_q2 AS (
    SELECT id FROM question
    WHERE topic_id = (SELECT id FROM topic WHERE slug = 'undoing-changes')
      AND language = 'tr'
      AND question = $$Yanlışlıkla `git add UserService.java` çalıştırdın ve düzenlemeni atmadan dosyayı unstage etmek istiyorsun. Hangi komutu kullanmalısın?$$
),
inserted_q2 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'tr', 'SINGLE_CHOICE', 'BEGINNER', 'PUBLISHED', 'CLAUDE',
           $$Yanlışlıkla `git add UserService.java` çalıştırdın ve düzenlemeni atmadan dosyayı unstage etmek istiyorsun. Hangi komutu kullanmalısın?$$, NULL, NULL,
           $$`git restore --staged`, düzenlemenin kendisine dokunmadan dosyayı staging area'dan working tree'ye geri taşır — yanlışlıkla yapılan bir `git add`'i, değişiklikleri koruyarak geri almak için tam olarak gereken budur.$$, 'n8n-ai-judge', '2026-08-29 15:08:40.461262',
           now(), now()
    FROM topic
    WHERE slug = 'undoing-changes'
      AND NOT EXISTS (SELECT 1 FROM existing_q2)
    RETURNING id
),
target_q2 AS (
    SELECT id, TRUE AS newly_inserted FROM inserted_q2
    UNION ALL
    SELECT id, FALSE AS newly_inserted FROM existing_q2
),
option_ins_q2 AS (
    INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT target_q2.id, v.option_text, v.is_correct, v.sort_order
    FROM target_q2
             CROSS JOIN (VALUES
    ($$git reset --hard HEAD~1$$, FALSE, 0),
    ($$git restore --staged UserService.java$$, TRUE, 1),
    ($$git revert HEAD$$, FALSE, 2),
    ($$git restore UserService.java$$, FALSE, 3)
        ) AS v(option_text, is_correct, sort_order)
    WHERE target_q2.newly_inserted
    RETURNING 1
)
INSERT INTO quiz_question_link (quiz_id, question_id, position)
SELECT quiz.id, target_q2.id, 2
FROM target_q2
         JOIN quiz ON TRUE
         JOIN topic t ON t.id = quiz.topic_id
WHERE t.slug = 'undoing-changes'
  AND quiz.language = 'tr'
  AND quiz.slug = 'default'
ON CONFLICT (quiz_id, question_id) DO NOTHING;


