           $$`git restore` HEAD'i asla taşımaz -- yalnızca working tree'ye ve `--staged` ile staging area'ya dokunur. HEAD'i önceki bir commit'e taşıyabilen komut `git reset`'tir.$$, 'n8n-ai-judge', '2026-08-29 15:08:40.508165',
           now(), now()
    FROM topic
    WHERE slug = 'undoing-changes'
      AND NOT EXISTS (SELECT 1 FROM existing_q9)
    RETURNING id
),
target_q9 AS (
    SELECT id, TRUE AS newly_inserted FROM inserted_q9
    UNION ALL
    SELECT id, FALSE AS newly_inserted FROM existing_q9
),
option_ins_q9 AS (
    INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT target_q9.id, v.option_text, v.is_correct, v.sort_order
    FROM target_q9
             CROSS JOIN (VALUES
    ($$`git restore --staged`, yalnızca stage durumunu değil, commit edilmemiş düzenlemenin kendisini de atar.$$, FALSE, 0),
    ($$`git reset`, HEAD'i önceki bir commit'e taşıyabilir -- `git restore` bunu asla yapmaz.$$, TRUE, 1),
    ($$`git restore` yalnızca working tree'ye (ve `--staged` ile staging area'ya) dokunur -- HEAD'i asla taşımaz.$$, TRUE, 2),
    ($$`git reset`, tıpkı `git revert` gibi, geçmişi değiştirmek yerine her zaman yeni bir commit oluşturur.$$, FALSE, 3)
        ) AS v(option_text, is_correct, sort_order)
    WHERE target_q9.newly_inserted
    RETURNING 1
)
INSERT INTO quiz_question_link (quiz_id, question_id, position)
SELECT quiz.id, target_q9.id, 9
FROM target_q9
