                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'tr', 'SINGLE_CHOICE', 'BEGINNER', 'PUBLISHED', 'CLAUDE',
           $$Dersin karar rehberine göre, yerel, push edilmemiş bir commit'i ve değişikliklerini tamamen atmak için hangi komutu kullanmalısın?$$, NULL, NULL,
           $$Dersin karar rehberi, yerel, push edilmemiş bir commit'i ve değişikliklerini tamamen atmak için `git reset --hard HEAD~1`'i listeler -- reset modları arasında en yıkıcı olanı.$$, 'n8n-ai-judge', '2026-08-29 15:08:40.514761',
           now(), now()
    FROM topic
    WHERE slug = 'undoing-changes'
      AND NOT EXISTS (SELECT 1 FROM existing_q10)
    RETURNING id
),
target_q10 AS (
